#!/usr/bin/env python3
import sys, os, re, io, csv, gzip, json
import xml.etree.ElementTree as ET
from datetime import date, datetime, timedelta, timezone
from decimal import Decimal, ROUND_HALF_UP

ORDER = ['central', 'south', 'east', 'river', 'north', 'west', 'harbor', 'lakeside']
FACT = {'kg': Decimal('1'), 'g': Decimal('0.001'), 'lb': Decimal('0.45359237'),
        'oz': Decimal('0.028349523125')}
UNIT_ALIAS = {'kg': 'kg', 'kgs': 'kg', 'g': 'g', 'gr': 'g', 'lb': 'lb', 'lbs': 'lb', 'oz': 'oz'}
MONTHS = {m: i + 1 for i, m in enumerate(
    ['jan', 'feb', 'mar', 'apr', 'may', 'jun', 'jul', 'aug', 'sep', 'oct', 'nov', 'dec'])}
COUNTED = {'delivered', 'delivered_late'}


# ---------- bytes / text ----------
def read_bytes(p):
    b = open(p, 'rb').read()
    if b[:2] == b'\x1f\x8b':
        b = gzip.decompress(b)
    return b


def decode(b):
    if b[:3] == b'\xef\xbb\xbf':
        return b[3:].decode('utf-8', 'replace')
    if b[:2] == b'\xff\xfe':
        return b[2:].decode('utf-16-le', 'replace')
    if b[:2] == b'\xfe\xff':
        return b[2:].decode('utf-16-be', 'replace')
    head = b[:2000]
    m = re.search(rb'^#[ \t]*charset[ \t]*:[ \t]*([A-Za-z0-9_.:-]+)', head, re.M)
    if m:
        try:
            return b.decode(m.group(1).decode('ascii'))
        except (LookupError, UnicodeDecodeError):
            return b.decode('latin-1')
    try:
        return b.decode('utf-8')
    except UnicodeDecodeError:
        return b.decode('latin-1')


# ---------- values ----------
def norm_id(s):
    m = re.match(r'^\s*SH\W*0*(\d+)\s*$', s or '', re.I)
    if not m:
        return None
    return int(m.group(1))


def norm_status(s):
    return re.sub(r'[\s\-]+', '_', (s or '').strip().lower())


def norm_unit(u):
    if u is None:
        return None
    return UNIT_ALIAS.get(u.strip().lower())


def parse_number(s, comma_decimal):
    s = s.strip().replace(' ', '')
    if comma_decimal:
        s = s.replace('.', '').replace(',', '.')
    else:
        s = s.replace(',', '')
    return Decimal(s)


WRE = re.compile(r'^\s*([+-]?[\d.,]+)\s*([A-Za-z]+)?\s*$')


def parse_weight(s, unit_chain, comma_decimal):
    """unit_chain: list of units by priority (first non-None used)."""
    m = WRE.match(s or '')
    if not m:
        return None
    num = parse_number(m.group(1), comma_decimal)
    u = norm_unit(m.group(2)) if m.group(2) else None
    if u is None:
        for c in unit_chain:
            c = norm_unit(c) if c else None
            if c:
                u = c
                break
    if u is None:
        u = 'kg'
    return num * FACT[u]


def parse_date(s, form):
    """Return a UTC date (datetime.date) or None."""
    s = (s or '').strip()
    if not s:
        return None
    m = re.match(r'^(\d{4})-(\d\d)-(\d\d)[T ](\d\d):(\d\d)(?::(\d\d)(?:[.,]\d+)?)?\s*(Z|z|[+-]\d\d(?::?\d\d)?)?$', s)
    if m:
        y, mo, d, hh, mi, ss, off = m.groups()
        dt = datetime(int(y), int(mo), int(d), int(hh), int(mi), int(ss or 0))
        if off and off.upper() != 'Z':
            sign = -1 if off[0] == '-' else 1
            digits = off[1:].replace(':', '')
            oh = int(digits[:2]); om = int(digits[2:4] or 0)
            dt = dt - sign * timedelta(hours=oh, minutes=om)
        return dt.date()
    f = (form or '').strip()
    fl = f.lower()
    if fl == 'serial' and re.match(r'^\d+(\.\d+)?$', s):
        return date(1899, 12, 30) + timedelta(days=int(Decimal(s)))
    m = re.match(r'^(\d{1,2})\s+([A-Za-z]{3})[A-Za-z]*\.?\s+(\d{4})$', s)
    if m and m.group(2).lower() in MONTHS:
        return date(int(m.group(3)), MONTHS[m.group(2).lower()], int(m.group(1)))
    if re.match(r'^\d{8}$', s) and fl in ('yyyymmdd', ''):
        return date(int(s[:4]), int(s[4:6]), int(s[6:]))
    if re.match(r'^\d{7}$', s) and fl in ('yyyyddd', ''):
        return date(int(s[:4]), 1, 1) + timedelta(days=int(s[4:]) - 1)
    parts = re.split(r'\D+', s)
    parts = [p for p in parts if p]
    if len(parts) == 3:
        a, b, c = parts
        if fl in ('iso', 'ymd', 'yyyy-mm-dd', 'yyyymmdd') or (len(a) == 4 and fl not in ('dmy', 'dd/mm/yyyy', 'mm/dd/yyyy', 'dd.mm.yyyy')):
            return date(int(a), int(b), int(c))
        if fl == 'mm/dd/yyyy':
            return date(int(c), int(a), int(b))
        # DMY, DD/MM/YYYY, DD.MM.YYYY
        return date(int(c), int(b), int(a))
    return None


def parse_type(t):
    t = (t or '').strip().lower()
    if t in ('', 'n', 'new'):
        return 'new'
    if t in ('c', 'cor', 'corr', 'correction', 'amend'):
        return 'correction'
    if t in ('v', 'void'):
        return 'void'
    return 'new'


# ---------- delimited ----------
COLS = {
    'east': ['id', 'type', 'shipped', 'gross', 'net', 'status', 'note'],
    'lakeside': ['id', 'kind', 'booked', 'shipped', 'gross_kg', 'net_kg', 'status'],
    'harbor': ['rec', 'ref', 'date', 'weight', 'state'],
    'river': ['t', 'ref', 'shipped', 'weight', 'status'],
    'west': ['id', 'typ', 'shipped', 'weight', 'status', 'note'],
}
SEP = {'east': ',', 'lakeside': ',', 'harbor': '|', 'river': '\t', 'west': ';'}
BASE_DATE = {'east': 'YMD', 'lakeside': 'iso', 'harbor': 'iso', 'river': 'MM/DD/YYYY', 'west': 'DD.MM.YYYY'}
BASE_UNIT = {'east': 'kg', 'lakeside': 'kg', 'harbor': 'kg', 'river': 'kg', 'west': 'kg'}
STATUS_CODES = {'dlv': 'delivered', 'dll': 'delivered_late', 'can': 'cancelled',
                'ret': 'returned', 'hld': 'held'}


def split_rows(lines, depot):
    """Yield ('comment', line) or ('row', fields)."""
    sep = SEP[depot]
    i = 0
    n = len(lines)
    while i < n:
        l = lines[i]
        i += 1
        if not l.strip():
            continue
        if l.startswith('#'):
            yield 'comment', l
            continue
        if sep == ',':
            while l.count('"') % 2 and i < n:
                l += '\n' + lines[i]
                i += 1
            try:
                r = next(csv.reader([l], delimiter=','))
            except Exception:
                r = l.split(',')
            yield 'row', r
        else:
            yield 'row', l.split(sep)


def parse_delimited(text, depot):
    lines = [x[:-1] if x.endswith('\r') else x for x in text.split('\n')]
    seq = None
    recs = []
    hdr = None
    known = set(COLS[depot])
    date_form = BASE_DATE[depot]
    unit_dir = None
    comma_dec = depot == 'west'
    for kind, v in split_rows(lines, depot):
        if kind == 'comment':
            if depot == 'harbor':
                m = re.search(r'seq\s*=\s*(\d+)', v)
                if m and seq is None:
                    seq = int(m.group(1))
            m = re.match(r'^#\s*([A-Za-z][A-Za-z _-]*?)\s*:\s*(.*?)\s*$', v)
            if m:
                name = re.sub(r'\s+', ' ', m.group(1).lower())
                val = m.group(2)
                if name == 'seq':
                    mm = re.match(r'\d+', val)
                    if mm and seq is None:
                        seq = int(mm.group(0))
                elif name in ('dates', 'date format', 'date', 'dateformat'):
                    date_form = val.split()[0] if val.split() else date_form
                elif name in ('unit', 'weight unit', 'weight-unit', 'weightunit'):
                    toks = val.split()
                    if toks:
                        unit_dir = toks[0]
                    if 'decimal comma' in val.lower():
                        comma_dec = True
                    elif 'decimal point' in val.lower() or 'decimal dot' in val.lower():
                        comma_dec = depot == 'west' and False
            continue
        r = v
        low = [x.strip().lower() for x in r]
        if len(low) >= 3 and all(x in known for x in low):
            hdr = low
            continue
        if hdr is None:
            hdr = list(COLS[depot])
        row = r
        extra_unit = None
        if len(row) == len(hdr) + 1:
            wi = weight_index(hdr)
            if wi is not None and wi + 1 < len(row) and norm_unit(row[wi + 1]):
                extra_unit = row[wi + 1]
                row = row[:wi + 1] + row[wi + 2:]
            else:
                for j, x in enumerate(row):
                    if norm_unit(x) and x.strip().lower() in UNIT_ALIAS:
                        extra_unit = x
                        row = row[:j] + row[j + 1:]
                        break
        if len(row) != len(hdr):
            if len(row) < len(hdr):
                row = row + [''] * (len(hdr) - len(row))
            else:
                continue
        d = dict(zip(hdr, [x for x in row]))
        rec = build_delim(depot, d, hdr, extra_unit, date_form, unit_dir, comma_dec)
        if rec:
            recs.append(rec)
    return seq, recs


def weight_index(hdr):
    for pat in (r'^gross(_(kg|g|lb|oz))?$', r'^weight(_(kg|g|lb|oz))?$'):
        for i, h in enumerate(hdr):
            if re.match(pat, h):
                return i
    return None


def build_delim(depot, d, hdr, extra_unit, date_form, unit_dir, comma_dec):
    idraw = d.get('id') or d.get('ref') or ''
    num = norm_id(idraw)
    if num is None:
        return None
    typ = parse_type(d.get('type') or d.get('kind') or d.get('rec') or d.get('typ') or d.get('t'))
    if typ == 'void':
        return {'num': num, 'type': 'void'}
    wi = weight_index(hdr)
    wname = hdr[wi]
    name_unit = None
    mm = re.search(r'_(kg|g|lb|oz)$', wname)
    if mm:
        name_unit = mm.group(1)
    w = parse_weight(d[wname], [name_unit, extra_unit, unit_dir, BASE_UNIT[depot]], comma_dec)
    sh = d.get('shipped') or d.get('date') or ''
    day = parse_date(sh, date_form)
    st = d.get('status') or d.get('state') or ''
    st = norm_status(st)
    st = STATUS_CODES.get(st, st)
    return {'num': num, 'type': typ, 'kg': w, 'date': day, 'counted': st in COUNTED}


# ---------- json lines ----------
def parse_north(text):
    seq = None
    recs = []
    for line in text.split('\n'):
        line = line.strip()
        if not line:
            continue
        try:
            v = json.loads(line)
        except Exception:
            continue
        items = v if isinstance(v, list) else [v]
        for o in items:
            if not isinstance(o, dict):
                continue
            if 'meta' in o and isinstance(o['meta'], dict):
                if seq is None and o['meta'].get('seq') is not None:
                    seq = int(o['meta']['seq'])
                continue
            num = norm_id(str(o.get('id', '')))
            if num is None:
                continue
            typ = o.get('kind')
            typ = 'correction' if typ == 'amend' else parse_type(typ)
            if typ == 'void':
                recs.append({'num': num, 'type': 'void'})
                continue
            w = None
            for k, val in o.items():
                m = re.match(r'^weight_(kg|g|lb|oz)$', k)
                if m:
                    w = parse_weight(str(val), [m.group(1)], False)
                    break
            if w is None and 'weight' in o:
                w = parse_weight(str(o['weight']), [o.get('unit')], False)
            day = parse_date(str(o.get('shipped_at', '')), 'iso')
            recs.append({'num': num, 'type': typ, 'kg': w, 'date': day,
                         'counted': norm_status(str(o.get('status', ''))) in COUNTED})
    return seq, recs


# ---------- xml ----------
def parse_central(raw):
    root = ET.fromstring(raw)
    seq = int(root.get('seq')) if root.get('seq') else None
    root_unit = root.get('weight-unit') or root.get('weight_unit')
    recs = []
    for el in root.iter('shipment'):
        num = norm_id(el.get('id', ''))
        if num is None:
            continue
        typ = parse_type(el.get('type'))
        if typ == 'void':
            recs.append({'num': num, 'type': 'void'})
            continue
        we = el.find('weight')
        w = None
        if we is not None and we.text:
            w = parse_weight(we.text, [we.get('unit'), root_unit, 'kg'], False)
        elif el.get('weight'):
            w = parse_weight(el.get('weight'), [el.get('unit'), root_unit, 'kg'], False)
        sh = el.get('shipped')
        se = el.find('shipped')
        if se is not None and se.text:
            sh = se.text
        day = parse_date(sh, '')
        st = el.find('status')
        st = norm_status(st.text if st is not None else el.get('status'))
        recs.append({'num': num, 'type': typ, 'kg': w, 'date': day, 'counted': st in COUNTED})
    return seq, recs


# ---------- south ----------
LAYOUTS = {
    'FW1': (42, dict(id=(0, 9), type=(9, 10), shipped=(10, 17), weight=(17, 25), status=(25, 26)), 'g', 'ddd'),
    'FW2': (43, dict(type=(0, 1), id=(1, 10), shipped=(10, 18), weight=(18, 26), status=(26, 27)), 'cg', 'ymd'),
    'FW3': (41, dict(id=(0, 9), shipped=(9, 16), type=(16, 17), weight=(17, 24), status=(24, 25)), 'dlb', 'ddd'),
}
BYLEN = {v[0]: k for k, v in LAYOUTS.items()}
SCODE = {'D': 'delivered', 'L': 'delivered_late', 'C': 'cancelled', 'R': 'returned', 'H': 'held'}


def parse_south(text):
    seq = None
    recs = []
    layout = None
    for line in text.split('\n'):
        if line.endswith('\r'):
            line = line[:-1]
        if line.startswith('#LAYOUT'):
            nm = line.split()[1].upper() if len(line.split()) > 1 else None
            if nm in LAYOUTS:
                layout = nm
            continue
        if line.startswith('#SEQ'):
            m = re.search(r'\d+', line)
            if m and seq is None:
                seq = int(m.group(0))
            continue
        if line.startswith('#') or line.startswith('\x0c') or not line.strip():
            continue
        if line.startswith('SOUTH DEPOT'):
            continue
        L = len(line)
        if L in BYLEN:
            lay = BYLEN[L]
        elif layout:
            lay = layout
            line = line.ljust(LAYOUTS[lay][0])
        else:
            continue
        ln, f, wk, dk = LAYOUTS[lay]
        g = lambda k: line[f[k][0]:f[k][1]]
        num = norm_id(g('id'))
        if num is None:
            continue
        typ = parse_type(g('type'))
        if typ == 'void':
            recs.append({'num': num, 'type': 'void'})
            continue
        wv = Decimal(int(g('weight')))
        if wk == 'g':
            kg = wv * FACT['g']
        elif wk == 'cg':
            kg = wv / 100
        else:
            kg = wv / 10 * FACT['lb']
        s = g('shipped')
        if dk == 'ddd':
            day = date(int(s[:4]), 1, 1) + timedelta(days=int(s[4:]) - 1)
        else:
            day = date(int(s[:4]), int(s[4:6]), int(s[6:8]))
        recs.append({'num': num, 'type': typ, 'kg': kg, 'date': day,
                     'counted': SCODE.get(g('status').strip().upper()) in COUNTED})
    return seq, recs


def parse_file(path, depot):
    b = read_bytes(path)
    if depot == 'central':
        return parse_central(b)
    text = decode(b)
    if depot == 'north':
        return parse_north(text)
    if depot == 'south':
        return parse_south(text)
    if depot in SEP:
        return parse_delimited(text, depot)
    return None, []


def q2(x):
    return float(x.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))


def main(data_dir, out_file):
    files = []
    for name in sorted(os.listdir(data_dir)):
        p = os.path.join(data_dir, name)
        if os.path.isfile(p):
            files.append((name.split('-')[0], name, p))
    depots = sorted({f[0] for f in files})
    current = {d: {} for d in depots}
    corrections = 0
    resends = 0
    byd = {}
    for d, name, p in files:
        try:
            seq, recs = parse_file(p, d)
        except Exception as e:
            sys.stderr.write('failed %s: %s\n' % (name, e))
            continue
        byd.setdefault(d, []).append((seq if seq is not None else -1, name, recs))
    for d, exps in byd.items():
        exps.sort(key=lambda x: (x[0], x[1]))
        cur = current[d]
        for seq, name, recs in exps:
            for r in recs:
                n = r['num']
                if r['type'] == 'new':
                    if n in cur:
                        resends += 1
                    else:
                        cur[n] = r
                elif r['type'] == 'correction':
                    cur[n] = r
                    corrections += 1
                else:
                    cur.pop(n, None)
                    corrections += 1
    rank = {d: i for i, d in enumerate(ORDER)}
    ordered = sorted(depots, key=lambda d: (rank.get(d, len(ORDER)), d))
    owner = {}
    handovers = set()
    for d in ordered:
        for n, r in current[d].items():
            if n in owner:
                handovers.add(n)
            else:
                owner[n] = (d, r)
    out_d = {d: [0, Decimal(0)] for d in depots}
    out_m = {}
    for n, (d, r) in owner.items():
        if not r.get('counted') or r.get('kg') is None or r.get('date') is None:
            continue
        out_d[d][0] += 1
        out_d[d][1] += r['kg']
        mk = '%04d-%02d' % (r['date'].year, r['date'].month)
        e = out_m.setdefault(mk, [0, Decimal(0)])
        e[0] += 1
        e[1] += r['kg']
    res = {
        'depots': {d: {'shipments': v[0], 'total_kg': q2(v[1])} for d, v in sorted(out_d.items())},
        'months': {k: {'shipments': v[0], 'total_kg': q2(v[1])} for k, v in sorted(out_m.items())},
        'corrections_applied': corrections,
        'resends_dropped': resends,
        'handovers': len(handovers),
    }
    with open(out_file, 'w') as f:
        json.dump(res, f, indent=2)
        f.write('\n')


if __name__ == '__main__':
    main(sys.argv[1], sys.argv[2])
